class LevelRegistry:
    """Consumers read name (non-empty str) and size (positive int) without checks."""

    def __init__(self):
        self.levels = {}

    def register(self, level):
        self.levels[level['name']] = level

    def area(self, name):
        size = self.levels[name]['size']
        return size * size


